ol" id="palabras_clave" name="palabras_clave" value="<?= old('palabras_clave',$audio['palabras_clave']??'') ?>" placeholder="noticias, campaña, verano"></div><div class="col-12"><label class="form-label" for="descripcion">Descripción</label><textarea class="form-control" id="descripcion" name="descripcion" rows="4"><?= old('descripcion',$audio['descripcion']??'') ?></textarea></div></div><div class="form-actions"><button class="btn btn-primary"><?= $editing?'Guardar cambios':'Cargar y guardar' ?></button></div></form>

